const LEG = P(101, [{c: 100.5, l: 100}, 101.8, [101.8, 104.6, 101.7, 104.4], [104.4, 107.6, 104.2, 107.4], 108.6, {c: 109.5, h: 110}, 108.8, 107.9, 107.2]);
const LEGD = P(119, [{c: 119.5, h: 120}, 118.3, [118.3, 118.4, 115.4, 115.6], [115.6, 115.8, 112.9, 113.1], {c: 112.4, l: 112}, 113.3, 114.1, 114.6]);
const SWP = P(106, [105.2, 104.1, {c: 103.4, l: 102.8}, 104.2, 105.3, 105.8, 104.9, 104, 103.5, [103.5, 103.7, 102.1, 103.3], [103.3, 105.6, 103.2, 105.4], 106.2, 105.7, 106.6]);
const SWE = P(108, [107.1, 106.2, {c: 105.5, l: 105}, 106.3, 107, 106.2, 105.6, [105.6, 105.8, 104.3, 105.2], [105.2, 108.1, 105.1, 107.9], [107.9, 108.8, 106.7, 108.5], 109.2]);
const SWEC = SWE.concat(P(109.2, [108.6, 107.6, {c: 107, l: 106.55}]));
