  chart: {curve: [{pts: [0, 2, 4.5, 6, 8.8, 11, 13.5, 15.2, 18, 20.6], label: 'logged'}, {pts: [0, 1, 1.5, .4, 2.1, 1.2, 2.9, 2, 1.1, 1.6], label: 'all trades', dash: true}], fmt: 'R', legend: true},
